              <input id="email" name="email" type="email" autocomplete="email" placeholder="you@example.com" aria-describedby="email-help" required>
              <button class="button button-primary" type="submit">Join the insider list</button>
            </form>
          </section>
        `;
      }

      function Footer() {
        return `
          <footer class="site-footer">
            <div class="footer-inner">
              <p>© 2026 Nocturne Supply Co. Curated retail for modern routines.</p>
              <nav class="footer-nav" aria-label="Footer">
                <ul>
