                  <li><a href="#newsletter">Contact</a></li>
                </ul>
              </nav>
            </div>
          </footer>
        `;
      }

      function App() {
        return `
          ${Header()}
          <main id="maincontent" tabindex="-1">
            ${Hero()}
            ${FeaturedProducts()}
            ${Deals()}
            ${Editorial()}
          </main>
          ${Footer()}
        `;
      }

      document.querySelector("#app").innerHTML = App();
    </script>
  </body>
</html>
