const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');

function renderedMarkup() {
  const html = fs.readFileSync('index.html', 'utf8');
  const script = html.match(/<script>([\s\S]*)<\/script>/)[1];
  let rendered = '';
  const document = { querySelector() { return { set innerHTML(value) { rendered = value; } }; } };
  new Function('document', script)(document);
  return { html, rendered };
}

(async () => {
  const { html, rendered } = renderedMarkup();
  const checks = {
    h1: (rendered.match(/<h1\b/g) || []).length,
    main: (rendered.match(/<main\b/g) || []).length,
    nav: (rendered.match(/<nav\b/g) || []).length,
    buttonLabels: (rendered.match(/aria-label="(?:Add to cart|Save item):/g) || []).length,
  };
  const structuralFailures = [];
  if (checks.h1 !== 1) structuralFailures.push(`expected 1 h1, found ${checks.h1}`);
  if (checks.main !== 1) structuralFailures.push(`expected 1 main, found ${checks.main}`);
  if (!html.includes('href="#maincontent"')) structuralFailures.push('skip link missing');
  if (!rendered.includes('id="maincontent" tabindex="-1"')) structuralFailures.push('main target not focusable');
  if (!rendered.includes('aria-label="Primary"') || !rendered.includes('aria-label="Footer"')) structuralFailures.push('nav labels missing');
  if (!rendered.includes('for="email"') || !rendered.includes('aria-describedby="email-help"') || !rendered.includes('required')) structuralFailures.push('email field label/help/required missing');
  if (structuralFailures.length) {
    console.log(JSON.stringify({ structuralFailures }, null, 2));
    process.exit(1);
  }

