       }

       .skip-link {
         background: var(--color-focus);
         border-radius: 999px;
         color: #041019;
         font-weight: 800;
         left: 1rem;
         padding: .75rem 1rem;
         position: fixed;
         top: 1rem;
         transform: translateY(-180%);
         z-index: 20;
       }

       .skip-link:focus {
         transform: translateY(0);
       }

       .site-header {
         backdrop-filter: blur(18px);
         background: #070911;
         border-bottom: 1px solid var(--color-border);
         position: sticky;
         top: 0;
         z-index: 10;
       }

       .header-inner,
       .section,
       .footer-inner {
         margin-inline: auto;
         max-width: var(--container);
         padding-inline: clamp(1rem, 4vw, 2rem);
       }

       .header-inner {
         align-items: center;
         display: flex;
         gap: 1rem;
         justify-content: space-between;
         min-height: 76px;
       }

       .brand {
         align-items: center;
         display: inline-flex;
         gap: .75rem;
         font-weight: 900;
         letter-spacing: -.03em;
       }

       .brand-mark {
         align-items: center;
         background:
           linear-gradient(135deg, var(--color-accent), var(--color-accent-strong));
         border-radius: 16px;
         color: #1b0f05;
         display: inline-flex;
         font-size: 1rem;
         height: 44px;
         justify-content: center;
         width: 44px;
       }

       .primary-nav ul,
       .footer-nav ul {
         display: flex;
         flex-wrap: wrap;
         gap: .25rem;
         list-style: none;
         margin: 0;
         padding: 0;
       }

       .primary-nav a,
       .footer-nav a {
         border-radius: 999px;
         color: var(--color-muted-text);
         display: inline-block;
         font-weight: 700;
         padding: .7rem .9rem;
       }

       .header-actions {
         display: flex;
         gap: .7rem;
       }

       .button {
         align-items: center;
         border: 1px solid var(--color-border);
         border-radius: 999px;
         color: var(--color-text);
         cursor: pointer;
         display: inline-flex;
         font-weight: 800;
         justify-content: center;
         min-height: 44px;
         padding: .75rem 1rem;
         text-align: center;
       }

       .button-primary {
         background: linear-gradient(135deg, var(--color-accent), var(--color-accent-strong));
         border-color: transparent;
         color: #1b0f05;
       }

       .button-secondary {
         background: var(--color-surface-strong);
       }

       .button-ghost {
         background: transparent;
       }

       .hero {
         padding-block: clamp(3rem, 8vw, 7rem) 2rem;
       }

       .hero-grid {
         display: grid;
         gap: 1.5rem;
         grid-template-columns: minmax(0, 1.1fr) minmax(280px, .9fr);
       }

       .hero-copy {
         background:
           linear-gradient(135deg, #151d30, #0d111d);
         border: 1px solid var(--color-border);
         border-radius: var(--radius-lg);
         box-shadow: var(--shadow-card);
         padding: clamp(1.5rem, 5vw, 4rem);
       }

       .eyebrow {
         color: var(--color-accent);
         font-size: .82rem;
         font-weight: 900;
         letter-spacing: .14em;
         margin: 0 0 .85rem;
         text-transform: uppercase;
       }

       h1,
       h2,
       h3 {
         line-height: 1.05;
         margin: 0;
       }

       h1 {
         font-size: clamp(2.75rem, 8vw, 6rem);
         letter-spacing: -.075em;
         max-width: 10ch;
       }

       h2 {
         font-size: clamp(2rem, 4vw, 3.25rem);
         letter-spacing: -.055em;
       }

       h3 {
         font-size: clamp(1.25rem, 2vw, 1.65rem);
         letter-spacing: -.035em;
       }

       .lede {
         color: var(--color-muted-text);
         font-size: clamp(1.05rem, 2vw, 1.25rem);
         margin: 1.35rem 0 0;
         max-width: 60ch;
       }

       .hero-actions {
         display: flex;
         flex-wrap: wrap;
         gap: .8rem;
         margin-top: 2rem;
       }

       .hero-panel {
         background:
           linear-gradient(160deg, #26344f, #131827 54%, #321f2b);
         border: 1px solid var(--color-border);
         border-radius: var(--radius-lg);
         box-shadow: var(--shadow-card);
         min-height: 520px;
         overflow: hidden;
         padding: 1.1rem;
         position: relative;
       }

       .hero-product {
         background:
           linear-gradient(145deg, #f6d365, #fda085);
         border-radius: 34px;
         color: #1d1108;
         display: grid;
         min-height: 100%;
         padding: clamp(1rem, 4vw, 2rem);
         place-items: end start;
       }

       .hero-product::before {
         background:
           radial-gradient(circle, #ffffff 0 12%, transparent 13%),
           radial-gradient(circle, #1d1108 0 9%, transparent 10%);
         border: 2px solid #1d1108;
         border-radius: 34px;
         content: "";
         display: block;
         height: min(34vw, 300px);
         margin: auto;
         width: min(34vw, 300px);
       }

       .hero-product p {
         font-size: 1.35rem;
         font-weight: 900;
         letter-spacing: -.04em;
         margin: 1rem 0 0;
         max-width: 15ch;
       }

       .section {
         padding-block: clamp(2.5rem, 7vw, 5.5rem);
       }

       .section-heading {
         align-items: end;
         display: flex;
         gap: 1rem;
         justify-content: space-between;
         margin-bottom: 1.5rem;
       }

       .section-heading p {
         color: var(--color-muted-text);
         margin: .65rem 0 0;
         max-width: 56ch;
       }

       .product-grid,
       .deal-grid,
       .editorial-grid {
         display: grid;
         gap: 1rem;
         list-style: none;
         margin: 0;
         padding: 0;
       }

       .product-grid {
         grid-template-columns: repeat(4, minmax(0, 1fr));
       }

       .deal-grid {
         grid-template-columns: repeat(3, minmax(0, 1fr));
       }

       .editorial-grid {
         grid-template-columns: 1.2fr .8fr;
       }

       .card,
       .deal-card,
       .story-card,
       .newsletter {
         background: var(--color-card);
         border: 1px solid var(--color-border);
         border-radius: var(--radius-md);
         box-shadow: 0 18px 44px #000000;
       }

       .card {
         display: flex;
         flex-direction: column;
         min-height: 100%;
         overflow: hidden;
       }

       .product-art {
         align-items: center;
         background: var(--product-bg);
         color: var(--product-fg);
         display: flex;
         font-size: clamp(3rem, 8vw, 5.5rem);
         justify-content: center;
         min-height: 210px;
       }

       .product-art span {
         filter: drop-shadow(0 12px 20px #000000);
       }

       .card-body,
       .deal-card,
       .story-card,
       .newsletter {
         padding: 1.25rem;
       }

       .card-kicker,
       .meta {
         color: var(--color-muted-text);
         font-size: .9rem;
         font-weight: 800;
       }

       .card h3,
       .deal-card h3,
       .story-card h3 {
         margin-top: .4rem;
       }

       .card p,
       .deal-card p,
       .story-card p,
       .newsletter p {
         color: var(--color-muted-text);
       }

       .price-row {
         align-items: baseline;
         display: flex;
         gap: .6rem;
         margin: 1rem 0;
       }

       .price {
         font-size: 1.25rem;
         font-weight: 900;
       }

       .old-price {
         color: var(--color-muted-text);
         text-decoration: line-through;
       }

       .card-actions {
         display: flex;
         gap: .65rem;
         margin-top: auto;
       }

       .card-actions .button {
         flex: 1;
       }

       .deal-card {
         background:
           linear-gradient(145deg, #171d2b, #101522);
         min-height: 280px;
       }

       .deal-badge {
         background: #203627;
         border: 1px solid #548366;
         border-radius: 999px;
         color: var(--color-success);
         display: inline-flex;
         font-size: .85rem;
         font-weight: 900;
         padding: .35rem .65rem;
       }

       .deal-card .button,
       .story-card .button,
       .newsletter .button {
         margin-top: 1rem;
       }

       .story-card:first-child {
         display: grid;
         grid-template-columns: .9fr 1.1fr;
         min-height: 360px;
         overflow: hidden;
         padding: 0;
       }

       .story-art {
         background:
           radial-gradient(circle at 35% 35%, #f6d365 0 16%, transparent 17%),
           linear-gradient(145deg, #273852, #4a2433);
         min-height: 240px;
       }

       .story-card:first-child .story-content {
         padding: clamp(1.25rem, 4vw, 2rem);
       }

       .newsletter {
         background:
           linear-gradient(145deg, #231a31, #101522);
       }

       .newsletter form {
         display: grid;
         gap: .75rem;
         margin-top: 1rem;
       }

       label {
         color: var(--color-text);
         font-weight: 800;
       }

       input {
         background: #090d16;
         border: 1px solid var(--color-border);
         border-radius: 999px;
         color: var(--color-text);
         font: inherit;
         min-height: 48px;
         padding: .75rem 1rem;
       }

       input::placeholder {
         color: #99a2b6;
       }

       .form-help {
         color: var(--color-muted-text);
         font-size: .9rem;
         margin: 0;
       }

       .site-footer {
         border-top: 1px solid var(--color-border);
         color: var(--color-muted-text);
         margin-top: 2rem;
       }

       .footer-inner {
         align-items: center;
         display: flex;
         gap: 1rem;
         justify-content: space-between;
         padding-block: 2rem;
       }

       @media (prefers-reduced-motion: no-preference) {
         html {
           scroll-behavior: smooth;
         }

         .card,
         .deal-card,
         .story-card,
         .button {
           transition: border-color .2s ease, transform .2s ease;
         }

         .card:hover,
         .deal-card:hover,
         .story-card:hover {
           border-color: var(--color-accent);
           transform: translateY(-3px);
         }
       }

       @media (max-width: 920px) {
         .header-inner,
         .footer-inner,
         .section-heading {
           align-items: flex-start;
           flex-direction: column;
         }

         .hero-grid,
         .editorial-grid,
         .story-card:first-child {
           grid-template-columns: 1fr;
         }

         .product-grid,
         .deal-grid {
           grid-template-columns: repeat(2, minmax(0, 1fr));
         }

         .hero-panel {
           min-height: 360px;
         }
       }

       @media (max-width: 560px) {
         .header-actions,
         .card-actions,
         .hero-actions {
           flex-direction: column;
           width: 100%;
         }

         .button {
           width: 100%;
         }

         .product-grid,
         .deal-grid {
           grid-template-columns: 1fr;
         }

         .primary-nav ul,
         .footer-nav ul {
           display: grid;
           grid-template-columns: repeat(2, minmax(0, 1fr));
           width: 100%;
         }
       }

       @media (forced-colors: active) {
         .button,
         .card,
         .deal-card,
         .story-card,
         .newsletter,
         .hero-copy,
         .hero-panel,
         input {
           border: 2px solid ButtonBorder;
           box-shadow: none;
         }

         .button-primary,
         .brand-mark,
         .skip-link {
           background: ButtonFace;
           color: ButtonText;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#maincontent">Skip to main content</a>
     <div id="app"></div>

     <script>
       const products = [
         {
           name: "Aurora Knit Jacket",
           category: "Outerwear",
           price: "$148",
           oldPrice: "$188",
           description: "Thermal knit layers with a tailored city silhouette.",
           icon: "◒",
           colors: ["#243854", "#f6d365"]
         },
         {
           name: "Carbon Weekender Tote",
           category: "Accessories",
           price: "$96",
           oldPrice: "",
           description: "Recycled nylon storage with laptop and shoe zones.",
           icon: "▰",
           colors: ["#3a253a", "#ff8f70"]
         },
         {
           name: "Lumen Ceramic Set",
           category: "Home",
           price: "$64",
           oldPrice: "$82",
           description: "Stackable matte dinnerware fired for daily use.",
           icon: "◌",
           colors: ["#173329", "#9de4b3"]
         },
         {
           name: "Pulse Runner",
           category: "Footwear",
           price: "$132",
           oldPrice: "",
           description: "Responsive soles and weather-ready woven uppers.",
           icon: "◖",
           colors: ["#172033", "#9fe7ff"]
         }
       ];

       const deals = [
         {
           title: "48-hour wardrobe reset",
           badge: "Save up to 35%",
           copy: "Build a capsule set with layered essentials, bags, and shoes."
         },
         {
           title: "Home refresh bundle",
           badge: "Buy 2, get 1",
           copy: "Mix tableware, candles, and soft goods for a refined night-in."
         },
         {
           title: "Free express delivery",
           badge: "Orders over $125",
           copy: "Members receive upgraded delivery and early deal access."
         }
       ];

       const stories = [
         {
           title: "The after-dark edit",
           meta: "Style guide",
           copy: "Our merch team pairs textured neutrals, luminous ceramics, and commuter-ready accessories for evenings that move from desk to dinner."
         },
         {
           title: "Designed to last longer",
           meta: "Sustainability",
           copy: "Meet the repairable fabrics, recycled fills, and modular details behind this season's most durable arrivals."
         }
       ];

       const navItems = [
         ["#featured", "Featured"],
         ["#deals", "Deals"],
         ["#editorial", "Editorial"],
         ["#newsletter", "Insider list"]
       ];

       function Header() {
         return `
           <header class="site-header">
             <div class="header-inner">
               <a class="brand" href="#" aria-label="Nocturne Supply Co. home">
                 <span class="brand-mark" aria-hidden="true">NS</span>
                 <span>Nocturne Supply Co.</span>
               </a>
               <nav class="primary-nav" aria-label="Primary">
                 <ul>
                   ${navItems.map(([href, label]) => `<li><a href="${href}">${label}</a></li>`).join("")}
                 </ul>
               </nav>
               <div class="header-actions">
                 <a class="button button-ghost" href="#featured">Shop new</a>
                 <a class="button button-primary" href="#deals">View deals</a>
               </div>
             </div>
           </header>
         `;
       }

       function Hero() {
         return `
           <section class="section hero" aria-labelledby="hero-heading">
             <div class="hero-grid">
               <div class="hero-copy">
                 <p class="eyebrow">Spring night market now open</p>
                 <h1 id="hero-heading">Retail essentials with after-dark energy.</h1>
                 <p class="lede">
                   Discover elevated apparel, home goods, and carry pieces curated for workdays,
                   weekends, and the moments between.
                 </p>
                 <div class="hero-actions">
                   <a class="button button-primary" href="#featured">Shop featured products</a>
                   <a class="button button-secondary" href="#editorial">Read the edit</a>
                 </div>
               </div>
               <div class="hero-panel">
                 <div class="hero-product">
                   <p>New launch: luminous layers for cool nights.</p>
                 </div>
               </div>
             </div>
           </section>
         `;
       }

       function ProductCard(product) {
         const oldPrice = product.oldPrice
           ? `<span class="old-price">${product.oldPrice}</span>`
           : "";

         return `
           <li>
             <article class="card">
               <div
                 class="product-art"
                 role="img"
                 aria-label="${product.name} abstract product illustration"
                 style="--product-bg: linear-gradient(145deg, ${product.colors[0]}, #0d111d); --product-fg: ${product.colors[1]};"
               >
                 <span aria-hidden="true">${product.icon}</span>
               </div>
               <div class="card-body">
                 <p class="card-kicker">${product.category}</p>
                 <h3><a href="#newsletter">${product.name}</a></h3>
                 <p>${product.description}</p>
                 <div class="price-row">
                   <span class="price">${product.price}</span>
                   ${oldPrice}
                 </div>
                 <div class="card-actions">
                   <button class="button button-primary" type="button" aria-label="Add to cart: ${product.name}">Add to cart</button>
                   <button class="button button-secondary" type="button" aria-label="Save item: ${product.name}">Save</button>
                 </div>
               </div>
             </article>
           </li>
         `;
       }

       function FeaturedProducts() {
         return `
           <section class="section" id="featured" aria-labelledby="featured-heading">
             <div class="section-heading">
               <div>
                 <p class="eyebrow">Featured products</p>
                 <h2 id="featured-heading">New arrivals with lasting utility.</h2>
                 <p>Shop the hero pieces our buyers selected for standout quality, flexible styling, and tactile finishes.</p>
               </div>
               <a class="button button-secondary" href="#newsletter">Get launch alerts</a>
             </div>
             <ul class="product-grid">
               ${products.map(ProductCard).join("")}
             </ul>
           </section>
         `;
       }

       function Deals() {
         return `
           <section class="section" id="deals" aria-labelledby="deals-heading">
             <div class="section-heading">
               <div>
                 <p class="eyebrow">Limited deals</p>
                 <h2 id="deals-heading">Offers worth moving on.</h2>
                 <p>Timed promotions across wardrobe staples, home refreshes, and member delivery perks.</p>
               </div>
             </div>
             <ul class="deal-grid">
               ${deals.map((deal) => `
                 <li>
                   <article class="deal-card">
                     <span class="deal-badge">${deal.badge}</span>
                     <h3>${deal.title}</h3>
                     <p>${deal.copy}</p>
                     <a class="button button-primary" href="#newsletter">Unlock ${deal.title}</a>
                   </article>
                 </li>
               `).join("")}
             </ul>
           </section>
         `;
       }

       function Editorial() {
         return `
           <section class="section" id="editorial" aria-labelledby="editorial-heading">
             <div class="section-heading">
               <div>
                 <p class="eyebrow">Editorial</p>
                 <h2 id="editorial-heading">Ideas for buying better.</h2>
                 <p>Guides and behind-the-scenes notes from the Nocturne buying desk.</p>
               </div>
             </div>
             <div class="editorial-grid">
               <article class="story-card">
                 <div class="story-art" role="img" aria-label="Abstract night market display with warm spotlight"></div>
                 <div class="story-content">
                   <p class="meta">${stories[0].meta}</p>
                   <h3>${stories[0].title}</h3>
                   <p>${stories[0].copy}</p>
                   <a class="button button-secondary" href="#newsletter">Read ${stories[0].title}</a>
                 </div>
               </article>
               <div class="story-stack">
                 <article class="story-card">
                   <p class="meta">${stories[1].meta}</p>
                   <h3>${stories[1].title}</h3>
                   <p>${stories[1].copy}</p>
                   <a class="button button-secondary" href="#newsletter">Read ${stories[1].title}</a>
                 </article>
                 ${Newsletter()}
               </div>
             </div>
           </section>
         `;
       }

       function Newsletter() {
         return `
           <section class="newsletter" id="newsletter" aria-labelledby="newsletter-heading">
             <p class="eyebrow">Insider list</p>
             <h3 id="newsletter-heading">Get early access to drops and private deals.</h3>
             <p id="email-help" class="form-help">Enter your email address to receive retail edits and launch notices.</p>
             <form action="#" method="post">
               <label for="email">Email address <span aria-hidden="true">*</span></label>
               <input id="email" name="email" type="email" autocomplete="email" placeholder="you@example.com" aria-describedby="email-help" required>
               <button class="button button-primary" type="submit">Join the insider list</button>
             </form>
           </section>
         `;
       }

       function Footer() {
         return `
           <footer class="site-footer">
             <div class="footer-inner">
               <p>© 2026 Nocturne Supply Co. Curated retail for modern routines.</p>
               <nav class="footer-nav" aria-label="Footer">
                 <ul>
                   <li><a href="#featured">Products</a></li>
                   <li><a href="#deals">Deals</a></li>
                   <li><a href="#editorial">Stories</a></li>
                   <li><a href="#newsletter">Contact</a></li>
                 </ul>
               </nav>
             </div>
           </footer>
         `;
       }

       function App() {
         return `
           ${Header()}
           <main id="maincontent" tabindex="-1">
             ${Hero()}
             ${FeaturedProducts()}
             ${Deals()}
             ${Editorial()}
           </main>
           ${Footer()}
         `;
       }

       document.querySelector("#app").innerHTML = App();
     </script>
   </body>
 </html>

')
